leerTokens().then(temprano => {
  lastStep = 'diagnostico_temprano';
  return cy.writeFile(`${EVIDENCIA}/G94-rev12-179-diagnostico-temprano.json`, _objectSpread(_objectSpread({}, temprano), {}, {
    brand_wait_ms: BRAND_WAIT_MS,
