});
cy.document({
  timeout: BRAND_WAIT_MS
}).should(doc => {
  const observado = leerBrand500Computed(doc);
  const theme = doc.documentElement.getAttribute('data-theme');
  const url = `${doc.location.origin}${doc.location.pathname}`;
  expect(theme, `data-theme debe ser light en ${BRAND_WAIT_MS}ms (observado=${theme === null ? 'null' : theme}, url=${url}). No se fuerza CSS.`).to.eq('light');
  expect(observado, `--brand-500 debe ser ${AJUSTADO} en ${BRAND_WAIT_MS}ms (observado=${observado || '(vacío)'}, data-theme=${theme === null ? 'null' : theme}, url=${url}, timeout=${BRAND_WAIT_MS}ms). Ver diagnostico-temprano.json. No se fuerza CSS.`).to.eq(AJUSTADO);
});
cy.then(() => {
  lastStep = 'brand_confirmado';
});
